import string

def roman(n: int) -> str:
    # Define the mapping of numbers to their corresponding Roman numerals.
    num_to_roman = {
        1000: "M", 900: "CM", 500: "D", 400: "CD",
        100: "C", 90: "XC", 50: "L", 40: "XL",
        10: "X", 9: "IX", 5: "V", 4: "IV", 1: "I"
    }

    result = ''
    for value, symbol in sorted(num_to_roman.items(), reverse=True):
        while n >= value:
            result += symbol
            n -= value
    return result

